## 并行函数调用

现代 LLM 支持在一次响应中同时发起多个工具调用，大幅提升执行效率。当多个工具调用之间没有依赖关系时，应该鼓励并行调用。

```mermaid
flowchart TD
    U["用户: 查询北京和上海的天气"] --> LLM["LLM 分析"]
    LLM --> TC1["Tool Call 1<br/>get_weather(北京)"]
    LLM --> TC2["Tool Call 2<br/>get_weather(上海)"]
    TC1 --> R1["结果: 晴 25°C"]
    TC2 --> R2["结果: 多云 22°C"]
    R1 --> LLM2["LLM 汇总"]
    R2 --> LLM2
    LLM2 --> A["北京晴天 25°C，上海多云 22°C"]
```

```python
import json
from openai import OpenAI

client = OpenAI()

def dispatch_tool(name: str, args: dict) -> dict:
    tool_registry = {
        "get_weather": get_weather,
        "search_knowledge_base": search_knowledge_base,
        "run_code": run_code
    }
    if name not in tool_registry:
        return {"error": f"未知工具: {name}"}
    return tool_registry[name](**args)

def agent_with_tools(user_message: str, tools: list) -> str:
    input_items = [{"role": "user", "content": user_message}]

    while True:
        response = client.responses.create(
            model="gpt-5.6-terra",
            input=input_items,
            tools=tools,
            parallel_tool_calls=True
        )

        # 把模型输出（含文本与 function_call 项）并入对话上下文
        input_items += response.output

        function_calls = [i for i in response.output if i.type == "function_call"]
        if not function_calls:
            return response.output_text

        for call in function_calls:
            result = dispatch_tool(call.name, json.loads(call.arguments))
            input_items.append({
                "type": "function_call_output",
                "call_id": call.call_id,
                "output": json.dumps(result, ensure_ascii=False)
            })
```

